def linear_search(items, target):
    for i in range(len(items)):
        if items[i] == target:
            return i
    return -1

nums = [4, 8, 15, 16, 23, 42]
print(linear_search(nums, 16))
print(linear_search(nums, 99))

def binary_search(items, target):
    low, high = 0, len(items) - 1
    while low <= high:
        mid = (low + high) // 2
        if items[mid] == target:
            return mid
        if items[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

nums = [1, 3, 5, 7, 9, 11, 13, 15]
print(binary_search(nums, 11))
print(binary_search(nums, 4))

def find_smallest_index(items):
    smallest = 0
    for i in range(1, len(items)):
        if items[i] < items[smallest]:
            smallest = i
    return smallest

def selection_sort(items):
    result = []
    src = list(items)          # копия, чтобы не портить исходный
    while src:
        idx = find_smallest_index(src)
        result.append(src.pop(idx))
    return result

print(selection_sort([29, 5, 71, 34, 10]))

def bubble_sort(items):
    arr = list(items)
    n = len(arr)
    for i in range(n):
        for j in range(n - 1 - i):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]  # обмен!
    return arr

print(bubble_sort([64, 25, 12, 90, 11]))

def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

print(factorial(5))

def rec_sum(items):
    if not items:          # пустой список - база
        return 0
    return items[0] + rec_sum(items[1:])

print(rec_sum([1, 2, 3, 4, 5]))

