from collections import deque

def bfs_path_exists(graph, start, target):
    queue = deque([start])
    visited = set()
    while queue:
        node = queue.popleft()      # берём из НАЧАЛА очереди
        if node == target:
            return True
        if node in visited:
            continue
        visited.add(node)
        queue.extend(graph[node])   # соседей - в конец очереди
    return False

graph = {'A': ['B', 'C'], 'B': ['D'], 'C': [], 'D': []}
print(bfs_path_exists(graph, 'A', 'D'))
print(bfs_path_exists(graph, 'C', 'A'))

